{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C04"],
      "claim": "Nocloprost, a prostaglandin analogue with a cyclopentanone, hydroxyl, and carboxylic acid side chain, had absolute oral bioavailability of about 2% in young male volunteers, indicating that this structural class undergoes extensive first-pass metabolism and poor systemic absorption.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C23"],
      "claim": "Testosterone undecanoate, a lipophilic fused-ring ester prodrug, had absolute oral bioavailability of 6.8 ± 3.3% in humans, showing that lipophilic fused-ring molecules with long alkyl chains can still have low systemic availability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "Fulvestrant, a lipophilic steroid with a long alkyl side chain and polar groups, has low oral bioavailability in humans, requiring intramuscular administration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C24"],
      "claim": "Myristic acid, a simple long-chain fatty acid, had 28% oral bioavailability in humans, suggesting that the carboxylic acid moiety can support absorption above the 20% threshold.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C15"],
      "claim": "Iloprost, a prostacyclin analogue, showed 56-63% absolute oral bioavailability in two TAO patients with an ER formulation, demonstrating that some prostaglandin analogues can achieve high oral availability under specific conditions.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a bicyclic prostaglandin E1 analogue with a cyclopentanone, cyclic ether, carboxylic acid, and difluoropentyl side chain. The most mechanistically relevant analogues—nocloprost and other lipophilic fused-ring acids—show low oral bioavailability (1-7%), consistent with extensive first-pass metabolism of prostaglandin-like structures. Simple fatty acids and a prostacyclin analogue with high values are less transferable due to structural simplicity or formulation/patient-specific effects. Therefore, F < 20% is better supported.",
  "evidence_gaps": [
    "No direct absolute bioavailability measurement for the query molecule.",
    "No analogue with the exact bicyclic acetal core was available.",
    "Iloprost high-bioavailability values come from an ER formulation and a small patient subset, limiting transferability.",
    "Simple fatty acid data do not capture the metabolic lability of the prostaglandin-like ring system."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

